<?php
namespace App\Http\Controllers; use App\Models\{Member,MembershipCategory,MembershipLevel}; use Illuminate\Http\Request; use Illuminate\Validation\Rule;
class MemberController extends Controller { private function lists(){return ['categories'=>MembershipCategory::where('is_active',true)->orderBy('name')->get(),'levels'=>MembershipLevel::where('is_active',true)->orderBy('fee')->get()];} private function rules(?Member $m=null){return ['first_name'=>'required|string|max:80','last_name'=>'required|string|max:80','email'=>['required','email',Rule::unique('members','email')->ignore($m)],'phone'=>'nullable|string|max:40','address'=>'nullable|string','membership_category_id'=>'required|exists:membership_categories,id','membership_level_id'=>'required|exists:membership_levels,id','status'=>'required|in:Active,Inactive','joined_at'=>'required|date'];} public function index(Request $r){$q=Member::with(['category','level']);if($s=$r->input('search'))$q->where(fn($x)=>$x->where('first_name','like',"%$s%")->orWhere('last_name','like',"%$s%")->orWhere('membership_number','like',"%$s%"));if($r->category)$q->where('membership_category_id',$r->category);if($r->level)$q->where('membership_level_id',$r->level);return view('members.index',['members'=>$q->latest()->paginate(12)->withQueryString()]+$this->lists());} public function create(){return view('members.form',['member'=>new Member(['joined_at'=>today(),'status'=>'Active'])]+$this->lists());} public function store(Request $r){$data=$r->validate($this->rules());$level=MembershipLevel::findOrFail($data['membership_level_id']);$data['membership_number']='MEM-'.now()->format('Y').'-'.str_pad((string)(Member::count()+1),5,'0',STR_PAD_LEFT);$data['expires_at']=now()->parse($data['joined_at'])->addMonths($level->validity_months);$m=\Illuminate\Support\Facades\DB::transaction(function()use($data){$m=Member::create($data); MemberVerificationController::send($m);return $m;});return redirect()->route('members.show',$m)->with('success','Member registered successfully.');} public function show(Member $member){$member->load(['category','level','transactions.payments']);return view('members.show',compact('member'));} public function edit(Member $member){return view('members.form',['member'=>$member]+$this->lists());} public function update(Request $r,Member $member){$data=$r->validate($this->rules($member));\Illuminate\Support\Facades\DB::transaction(function()use($member,$data){$changed=$member->email!==$data['email']; if($changed)$member->forceFill(['email_verified_at'=>null,'email_verification_token'=>null]);$member->fill($data)->save();if($changed)MemberVerificationController::send($member);});return redirect()->route('members.show',$member)->with('success','Member updated.');} public function deactivate(Member $member){$member->update(['status'=>'Inactive']);return back()->with('success','Member deactivated.');} public function destroy(Member $member){$member->delete();return redirect()->route('members.index')->with('success','Member deleted.');} public function history(Member $member){$transactions=$member->transactions()->with(['level','payments'])->latest()->paginate(15);return view('members.history',compact('member','transactions'));} }
